<?php
declare(strict_types=1);
namespace Hostider\OfflineBackup;
use Hostider\Core\Database\{Database,Migrator};
use Hostider\Finance\Decimal;
final readonly class NativeSchema
{
 private function __construct(public array $tables,public array $triggers,public array $foreign,public array $checks,public array $migration){}
 public static function capture(Database $db):self{Guard::database($db);(new Migrator($db,dirname(__DIR__,2).'/migrations'))->assertReady();$tables=[];$schema=$db->execute('SELECT DATABASE()')->fetchColumn();$rows=$db->execute("SELECT TABLE_NAME,TABLE_TYPE,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME<>'f6f_control' ORDER BY TABLE_NAME")->fetchAll();Guard::require(count($rows)>0&&count($rows)<=512,'TABLE_BOUND');foreach($rows as $v){$n=$v['TABLE_NAME'];Guard::name($n);Guard::require($v['TABLE_TYPE']==='BASE TABLE'&&$v['ENGINE']==='InnoDB','BASE_TABLES_ONLY');$ddl=$db->execute('SHOW CREATE TABLE '.Guard::name($n))->fetch(\PDO::FETCH_NUM)[1];$cols=$db->execute('SELECT COLUMN_NAME,DATA_TYPE,COLUMN_TYPE,IS_NULLABLE,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION',[$n])->fetchAll();Guard::require(count($cols)>0&&count($cols)<=128,'COLUMN_BOUND');foreach($cols as $c){Guard::name($c['COLUMN_NAME']);Guard::require(!in_array($c['DATA_TYPE'],['float','double'],true),'EXACT_SCALARS');}$pk=$db->execute("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION",[$n])->fetchAll(\PDO::FETCH_COLUMN);Guard::require($pk!==[],'PRIMARY_KEY_REQUIRED');$tables[$n]=['ddl'=>self::normalize($ddl),'columns'=>$cols,'primary'=>$pk];}
 $triggers=$db->execute('SELECT TRIGGER_NAME,EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_TIMING,ACTION_STATEMENT,SQL_MODE,CHARACTER_SET_CLIENT,COLLATION_CONNECTION,DATABASE_COLLATION FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() ORDER BY TRIGGER_NAME')->fetchAll();Guard::require(count($triggers)<=1024,'TRIGGER_BOUND');foreach($triggers as $t){Guard::name($t['TRIGGER_NAME']);Guard::require(isset($tables[$t['EVENT_OBJECT_TABLE']]),'TRIGGER_SCOPE');}
 Guard::require((int)$db->execute('SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE()')->fetchColumn()===0&&(int)$db->execute('SELECT COUNT(*) FROM information_schema.EVENTS WHERE EVENT_SCHEMA=DATABASE()')->fetchColumn()===0,'EXECUTABLE_OBJECTS');
 $fk=[];foreach($db->execute('SELECT TABLE_NAME,CONSTRAINT_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME,REFERENCED_TABLE_SCHEMA FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL ORDER BY TABLE_NAME,CONSTRAINT_NAME,ORDINAL_POSITION')->fetchAll() as $v){Guard::require($v['REFERENCED_TABLE_SCHEMA']===$schema&&isset($tables[$v['REFERENCED_TABLE_NAME']]),'FOREIGN_SCOPE');$k=$v['TABLE_NAME'].':'.$v['CONSTRAINT_NAME'];$fk[$k]??=['table'=>$v['TABLE_NAME'],'parent'=>$v['REFERENCED_TABLE_NAME'],'columns'=>[],'references'=>[]];$fk[$k]['columns'][]=$v['COLUMN_NAME'];$fk[$k]['references'][]=$v['REFERENCED_COLUMN_NAME'];}
 $checks=$db->execute('SELECT TABLE_NAME,CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() ORDER BY TABLE_NAME,CONSTRAINT_NAME')->fetchAll();$migration=[];foreach(glob(dirname(__DIR__,2).'/migrations/*.php') as $p){$migration[basename($p)]=hash_file('sha256',$p);}ksort($migration);return new self($tables,$triggers,array_values($fk),$checks,$migration);
 }
 public static function normalize(string $ddl):string{return preg_replace('/ AUTO_INCREMENT=[0-9]+/','',$ddl);}
 public function fingerprint():string{return Guard::hash([$this->tables,$this->triggers,$this->foreign,$this->checks,$this->migration]);}
 public function assertSchema(Database $db):void{Guard::require(self::capture($db)->fingerprint()===$this->fingerprint(),'SCHEMA_DRIFT');}
 public function lock(Database $db):void{Guard::database($db);$q=[];foreach(array_keys($this->tables) as $t){$q[]=Guard::name($t).' READ';}$q[]='f6f_control READ';foreach($this->foreign as $i=>$f){$q[]=Guard::name($f['table']).' AS '.Guard::name('f6f_c_'.$i).' READ';$q[]=Guard::name($f['parent']).' AS '.Guard::name('f6f_p_'.$i).' READ';}$sql='LOCK TABLES '.implode(',',$q);Guard::require(strlen($sql)<=131072,'LOCK_BOUND');$db->execute($sql);}
 public function integrity(Database $db):void{Guard::database($db);foreach($this->foreign as $i=>$f){$c='f6f_c_'.$i;$p='f6f_p_'.$i;$join=[];$notnull=[];foreach($f['columns'] as $n=>$col){$join[]=Guard::name($c).'.'.Guard::name($col).'='.Guard::name($p).'.'.Guard::name($f['references'][$n]);$notnull[]=Guard::name($c).'.'.Guard::name($col).' IS NOT NULL';}$sql='SELECT 1 FROM '.Guard::name($f['table']).' AS '.Guard::name($c).' LEFT JOIN '.Guard::name($f['parent']).' AS '.Guard::name($p).' ON '.implode(' AND ',$join).' WHERE '.implode(' AND ',$notnull).' AND '.Guard::name($p).'.'.Guard::name($f['references'][0]).' IS NULL LIMIT 1';Guard::require(!$db->execute($sql)->fetchColumn(),'FOREIGN_DATA');}foreach($this->checks as $c){Guard::require(!$db->execute('SELECT 1 FROM '.Guard::name($c['TABLE_NAME']).' WHERE NOT('.$c['CHECK_CLAUSE'].') LIMIT 1')->fetchColumn(),'CHECK_DATA');}}
 public function snapshot(Database $db):array{$this->assertSchema($db);$this->integrity($db);$out=[];$meta=[];$total=0;$bytes=0;$cells=0;foreach($this->tables as $n=>$t){$cols=array_column($t['columns'],'COLUMN_NAME');$sum=implode('+',array_map(fn($c)=>'COALESCE(OCTET_LENGTH('.Guard::name($c).'),0)',$cols));$probe=$db->execute('SELECT COUNT(*) n,COALESCE(SUM(b),0) bytes,COALESCE(MAX(b),0) largest FROM(SELECT '.$sum.' b FROM '.Guard::name($n).' LIMIT '.(Guard::MAX_ROWS+1).') f6f_bound')->fetch();$total+=(int)$probe['n'];$bytes+=(int)$probe['bytes'];$cells+=(int)$probe['n']*count($cols);Guard::require($total<=Guard::MAX_ROWS&&$bytes<=Guard::MAX_DB&&(int)$probe['largest']<=131072&&$cells<=100000&&memory_get_usage(true)<83_886_080,'DB_BOUND');$stmt=$db->execute('SELECT * FROM '.Guard::name($n).' ORDER BY '.implode(',',array_map(Guard::name(...),$t['primary'])));$rows=[];while($row=$stmt->fetch(\PDO::FETCH_NUM)){$v=array_map(fn($x)=>$x===null?null:base64_encode((string)$x),$row);Guard::require(strlen(\Hostider\Core\CanonicalJson::encode($v))<=200000,'ROW_BOUND');$rows[]=$v;}$out[$n]=$rows;$create=$db->execute('SHOW CREATE TABLE '.Guard::name($n))->fetch(\PDO::FETCH_NUM)[1];$meta[$n]=['schema'=>$create,'columns'=>$cols];}self::finance($out,$meta);return ['tables'=>$out,'metadata'=>$meta];}
 public function validate(array $image):array{Guard::require($image['header']['schema_fingerprint']===$this->fingerprint()&&$image['header']['migrations']===$this->migration&&Guard::hash($image['header']['triggers'])===Guard::hash($this->triggers),'MIGRATION_OR_SCHEMA');Guard::require(array_keys($image['tables'])===array_keys($this->tables),'TABLE_SET');foreach($this->tables as $n=>$t){$meta=$image['metadata'][$n];Guard::require(self::normalize($meta['schema'])===$t['ddl']&&$meta['columns']===array_column($t['columns'],'COLUMN_NAME'),'TABLE_SCHEMA');$seen=[];$indexes=array_map(fn($c)=>array_search($c,$meta['columns'],true),$t['primary']);foreach($image['tables'][$n] as $row){Guard::require(count($row)===count($meta['columns']),'ROW_COLUMNS');$key=Guard::hash(array_map(fn($i)=>$row[$i],$indexes));Guard::require(!isset($seen[$key]),'DUPLICATE_ROW');$seen[$key]=true;}}
 $m=[];foreach(self::plain($image['tables']['schema_migrations'],$image['metadata']['schema_migrations']['columns']) as $row){Guard::require($row['status']==='APPLIED'&&isset($this->migration[$row['version']])&&$row['checksum']===$this->migration[$row['version']],'MIGRATION_ROWS');$m[$row['version']]=$row['checksum'];}ksort($m);Guard::require($m===$this->migration,'MIGRATION_SET');return self::finance($image['tables'],$image['metadata']);}
 public static function plain(array $rows,array $columns):array{return array_map(function($row)use($columns){return array_combine($columns,array_map(fn($v)=>$v===null?null:base64_decode($v,true),$row));},$rows);}
 public static function finance(array $tables,array $meta):array{$journals=self::plain($tables['finance_journals'],$meta['finance_journals']['columns']);$lines=self::plain($tables['finance_lines'],$meta['finance_lines']['columns']);$sums=[];$totals=[];foreach($journals as $j){$sums[$j['id']]=['currency'=>$j['currency'],'DEBIT'=>new Decimal('0'),'CREDIT'=>new Decimal('0'),'lines'=>0];}foreach($lines as $line){Guard::require(isset($sums[$line['journal_id']])&&in_array($line['side'],['DEBIT','CREDIT'],true),'LEDGER_REFERENCE');$v=new Decimal($line['amount_minor']);Guard::require($v->compare(new Decimal('0'))>0,'LEDGER_AMOUNT');$sums[$line['journal_id']][$line['side']]=$sums[$line['journal_id']][$line['side']]->add($v);++$sums[$line['journal_id']]['lines'];}foreach($sums as $v){Guard::require($v['lines']>=2&&$v['DEBIT']->compare($v['CREDIT'])===0,'LEDGER_UNBALANCED');$c=$v['currency'];$totals[$c]??=['DEBIT'=>'0','CREDIT'=>'0'];foreach(['DEBIT','CREDIT'] as $s){$totals[$c][$s]=(string)(new Decimal($totals[$c][$s]))->add($v[$s]);}}ksort($totals);return ['journals'=>count($journals),'lines'=>count($lines),'totals'=>$totals,'balanced'=>true];}
 public function import(Workspace $workspace,array $image,?\Closure $hook=null):void{$workspace->fence();Guard::require($workspace->state()['target_state']==='RESTORING','IMPORT_TARGET_STATE');$db=$workspace->db('target');Guard::database($db,['target']);$this->validate($image);$sqlmode=$db->execute('SELECT @@sql_mode')->fetchColumn();$db->execute('SET SESSION foreign_key_checks=0');$db->execute('SET SESSION check_constraint_checks=1');try{foreach($this->triggers as $t){$db->execute('DROP TRIGGER '.Guard::name($t['TRIGGER_NAME']));}$db->execute("SET SESSION sql_mode=CONCAT(@@sql_mode,',NO_AUTO_VALUE_ON_ZERO')");$db->transaction(function()use($db,$image,$hook):void{foreach(array_keys($this->tables) as $n){$db->execute('DELETE FROM '.Guard::name($n));}foreach($this->tables as $n=>$t){$cols=[];$indexes=[];foreach($t['columns'] as $i=>$c){if(!str_contains($c['EXTRA'],'STORED GENERATED')&&!str_contains($c['EXTRA'],'VIRTUAL GENERATED')){$cols[]=Guard::name($c['COLUMN_NAME']);$indexes[]=$i;}}$stmt=$db->pdo->prepare('INSERT INTO '.Guard::name($n).'('.implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')');foreach($image['tables'][$n] as $row){$stmt->execute(array_map(fn($i)=>$row[$i]===null?null:base64_decode($row[$i],true),$indexes));if($hook!==null){$hook('restore_row',$n);}}}});$db->execute('SET SESSION sql_mode=?',[$sqlmode]);$triggerSql=[];foreach(glob(dirname(__DIR__,2).'/migrations/*.php') as $p){$statements=(static fn($path)=>require $path)($p);foreach($statements as $sql){if(preg_match('/\ACREATE TRIGGER `?([a-z0-9_]+)`? /i',$sql,$m)===1){$triggerSql[$m[1]]=$sql;}elseif(preg_match('/\ADROP TRIGGER (?:IF EXISTS )?`?([a-z0-9_]+)`?/i',$sql,$m)===1){unset($triggerSql[$m[1]]);}}}$names=array_column($this->triggers,'TRIGGER_NAME');$keys=array_keys($triggerSql);sort($names);sort($keys);Guard::require($names===$keys,'TRUSTED_FINAL_TRIGGER_SET');foreach($triggerSql as $sql){$db->execute($sql);}foreach($image['metadata'] as $n=>$v){if(preg_match('/ AUTO_INCREMENT=([0-9]{1,20})/',$v['schema'],$m)){$db->execute('ALTER TABLE '.Guard::name($n).' AUTO_INCREMENT='.$m[1]);}}}finally{$db->execute('SET SESSION foreign_key_checks=1');$db->execute('SET SESSION sql_mode=?',[$sqlmode]);}$this->assertSchema($db);$this->integrity($db);}
}
